//! @file
//! Task T2 of
//! docs/superpowers/plans/2026-09-30-fermion-longrange-hamiltonian.md: a
//! long-range fermion gate chain (tool/tenes_std.py, task T1) run through the
//! real simple-update driver iTPS<tensor>::simple_update(const
//! EvolutionOperator&), and the load-time inference of the parity ledgers
//! (infer_fermion_gate_ledgers, design section 6.1). Behaviour contract:
//! "振る舞い契約書(T2)" of the plan; design
//! docs/superpowers/specs/2026-09-30-fermion-longrange-hamiltonian-design.md.
//!
//! Where the numbers come from (test/fermion/gen_longrange_gate.py, which
//! writes the GENERATED block below):
//!   - the gate chains are tenes_std's output for a two-site Hamiltonian;
//!   - the expected ledger of every gate leg is read off the chain's nonzero
//!     elements with the rule of design section 6.1;
//!   - the reference overlaps <phi_k|psi> and <phi_k|O_st psi> come from a
//!     Fock-space construction (a sparse generalisation of fock_oracle.py,
//!     checked against it) with O_st built from creation/annihilation
//!     operators in the source-first ordered basis of design section 3 and
//!     evo = expm(-tau H) computed there with scipy. Neither the sign formula
//!     of tenes_std (design 4.1) nor anything of the simple update enters
//!     the reference.
//!
//! How the comparison works (contract item 1). The unit-cell tensors are
//! set here from the deterministic formula of fock_oracle.py, nonzero only
//! on one even and one odd label of every virtual leg (the Fock oracle
//! distinguishes one label per parity on a bond). The virtual dimension of
//! the bonds the chain crosses is 16 (d = 2) or 32 (d = 4 on the path), at
//! least the rank the chain can create there (checked after every gate, see
//! lg_apply), so the simple update truncates nothing, and it keeps the
//! environment exact (lambda = 1 at the start; it multiplies and divides
//! back the same lambda on the other legs).
//! After the chain, an open patch around the path (every leg on its
//! perimeter fixed to label 0, which is even) is contracted with the graded
//! tensordot into its physical state psi', and <phi_k|psi'> for six fixed
//! dense bras phi_k is compared with the reference <phi_k|O_st psi> up to
//! one overall complex factor:
//!     residual = |g - c w| / |g|,  c = <w, g> / <w, w>,  must be <= 1e-10.
//! The same contraction of the state before the update is compared with
//! <phi_k|psi> first (the [truth] calibration): it pins the patch
//! contraction to the oracle's Fock convention, so that the comparison after
//! the update can only fail through the update itself.
//!
//! Patch geometry: the 4x4 cell is larger than any path here (at most three
//! hops), so every patch position is a different unit-cell site, the
//! translated copies of the chain never touch the patch, and the perimeter
//! legs are on bonds no gate acts on. The state of the patch after the
//! chain is therefore exactly O_st applied to the state before.
//!
//! Test cases (contract items in brackets):
//!   T2-1-self, T2-1-calibration [1]  [truth]: coverage of design 4.3 and of
//!             both raster-reversed hop directions; the patch contraction
//!             before the update against the oracle. Green before T2.
//!   T2-1a..f  [1] the chains through the driver against O_st psi: d = 2
//!             hopping and density (every displacement of design 4.3),
//!             complex, mixed site kinds, chi = d, d = 4.
//!   T2-2      [2] a unit-cell site that comes back on the path (2x2 cell):
//!             exact agreement with the same gates on a 4x2 supercell.
//!   T2-3      [3] the physical ledger after every gate of a chain.
//!   T2-4a..e  [4] infer_fermion_gate_ledgers: accepted chains and their
//!             ledgers, identity completion, rejections, the full update,
//!             bosonic input.
//! Cases tagged [mpi2] are registered a second time at two ranks (item 5).

