// ---- generated data layout -------------------------------------------------

//! One nonzero element (in1, in2, out1, out2) of a gate.
struct lg_entry {
  int i[4];
  double re;
  double im;
};

//! One gate of a chain: the bond it acts on, its shape, the ledgers of its
//! four legs expected from the rule of design section 6.1 ("0"/"1" per
//! index, legs in1, in2, out1, out2), and its nonzero elements.
struct lg_gate_data {
  int source_site;
  int source_leg;
  int dims[4];
  std::array<const char*, 4> legs;
  const lg_entry* entries;
  std::size_t nentries;
};

//! One long-range bond (source, dx, dy) with its chain and its reference.
//! kinds: per unit-cell site, 0 = spinless (d = 2, parity [0, 1]),
//! 1 = spinless with swapped labels (d = 2, [1, 0]), 2 = Hubbard (d = 4,
//! [0, 1, 1, 0]). vdims: per site (l, t, r, b). The patch has nrow x ncol
//! positions in raster order (row 0 on top); psites is the unit-cell site
//! at each position, ppos the position of each site of the path.
struct lg_case_data {
  const char* name;
  int lx;
  int ly;
  int source;
  int dx;
  int dy;
  bool is_complex;
  int seed;
  std::vector<int> kinds;
  std::vector<std::array<int, 4>> vdims;
  std::vector<lg_gate_data> gates;
  int nrow;
  int ncol;
  std::vector<int> psites;
  std::vector<int> ppos;
  std::vector<std::array<double, 2>> before;
  std::vector<std::array<double, 2>> after;
};

//! Contract item 2: a chain in a 2x2 cell on which a unit-cell site comes
//! back (no reference state; see T2-2).
struct lg_revisit_data {
  const char* name;
  int lx;
  int ly;
  int source;
  int dx;
  int dy;
  int seed;
  std::vector<int> kinds;
  std::vector<std::array<int, 4>> vdims;
  std::vector<lg_gate_data> gates;
};

